import os
from typing import Any, Dict, List, Optional

from openai import AzureOpenAI


def _extract_text(response: Any) -> str:
    if response is None:
        return ""
    if isinstance(response, str):
        return response
    if hasattr(response, "model_dump"):
        response = response.model_dump()
    if isinstance(response, dict):
        choices = response.get("choices") or []
        if choices:
            choice0 = choices[0]
            if isinstance(choice0, dict):
                message = choice0.get("message") or {}
                content = message.get("content")
                if isinstance(content, list):
                    parts: List[str] = []
                    for item in content:
                        if isinstance(item, dict):
                            text = item.get("text")
                            if text:
                                parts.append(str(text))
                        elif item is not None:
                            parts.append(str(item))
                    return "".join(parts).strip()
                if content is not None:
                    return str(content).strip()
                text = choice0.get("text")
                if text is not None:
                    return str(text).strip()
    content = getattr(response, "choices", None)
    if content:
        choice0 = content[0]
        message = getattr(choice0, "message", None)
        if message is not None:
            value = getattr(message, "content", None)
            if value is not None:
                return str(value).strip()
        text = getattr(choice0, "text", None)
        if text is not None:
            return str(text).strip()
    return str(response).strip()


def invoke_managed_model(
    prompt: str,
    deployment: Optional[str] = None,
    system_prompt: Optional[str] = None,
    temperature: float = 0.2,
    max_tokens: int = 256,
) -> Dict[str, Any]:
    endpoint = os.environ.get("AZURE_OPENAI_ENDPOINT")
    api_key = os.environ.get("AZURE_OPENAI_API_KEY")
    api_version = os.environ.get("AZURE_OPENAI_API_VERSION", "2024-06-01")

    if not endpoint or not api_key:
        raise EnvironmentError(
            "AZURE_OPENAI_ENDPOINT and AZURE_OPENAI_API_KEY must be set for Azure OpenAI."
        )

    model = deployment or os.environ.get("AZURE_OPENAI_DEPLOYMENT")
    if not model:
        raise EnvironmentError(
            "A deployment name must be provided via argument or AZURE_OPENAI_DEPLOYMENT."
        )

    client = AzureOpenAI(
        azure_endpoint=endpoint,
        api_key=api_key,
        api_version=api_version,
    )

    messages: List[Dict[str, str]] = []
    if system_prompt:
        messages.append({"role": "system", "content": system_prompt})
    messages.append({"role": "user", "content": prompt})

    response = client.chat.completions.create(
        model=model,
        messages=messages,
        temperature=temperature,
        max_tokens=max_tokens,
    )

    text = _extract_text(response)

    return {
        "provider": "azure_openai",
        "deployment": model,
        "text": text,
        "raw": response,
    }
